{"command":"mkdir -p /workspace && cd /workspace && cat > args.go <<'EOF'
package main

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
)

// optionKind describes how an option consumes arguments.
type optionKind int

const (
	kindBool optionKind = iota
	kindInt
	kindUint
	kindString
	kindStringList
	kindChoice
)

// optionSpec is the static description of a command line option.
type optionSpec struct {
	short     byte
	long      string
	valueName string
	desc      string
	def       string
	kind      optionKind
	choices   []string
}

// label renders the option the way error messages refer to it.
func (o *optionSpec) label() string {
	if o.short != 0 {
		return fmt.Sprintf("-%c, --%s", o.short, o.long)
	}
	return "--" + o.long
}

func (o *optionSpec) canArgument() bool {
	return o.kind != kindBool
}

func (o *optionSpec) isSignedNumber() bool {
	return o.kind == kindInt
}

// arguments holds all parsed command line values.
type arguments struct {
	acceptedStatusCodes    string
	bufferSize             int
	maxConnections         int
	maxConnectionsPerHost  int
	maxResponseBodySize    int
	excludes               []string
	includes               []string
	followRobotsTxt        bool
	followSitemapXML       bool
	headers                []string
	ignoreFragments        bool
	maxRetries             uint
	dnsResolver            string
	format                 string
	jsonOutput             bool
	experimentalVerboseJSON bool
	junitOutput            bool
	maxRedirections        int
	rateLimit              int
	timeout                int
	verbose                bool
	proxy                  string
	skipTLSVerification    bool
	onePageOnly            bool
	color                  string
	help                   bool
	version                bool

	positional []string
}

func defaultArguments() *arguments {
	return &arguments{
		acceptedStatusCodes:   "200..300",
		bufferSize:            4096,
		maxConnections:        512,
		maxConnectionsPerHost: 512,
		maxResponseBodySize:   10000000,
		maxRedirections:       64,
		timeout:               10,
		format:                "text",
		color:                 "auto",
	}
}

var optionSpecs = []*optionSpec{
	{long: "accepted-status-codes", valueName: "<codes>", desc: "Accepted HTTP response status codes (e.g. '200..300,403')", def: "200..300", kind: kindString},
	{short: 'b', long: "buffer-size", valueName: "<size>", desc: "HTTP response buffer size in bytes", def: "4096", kind: kindInt},
	{short: 'c', long: "max-connections", valueName: "<count>", desc: "Maximum number of HTTP connections", def: "512", kind: kindInt},
	{long: "max-connections-per-host", valueName: "<count>", desc: "Maximum number of HTTP connections per host", def: "512", kind: kindInt},
	{long: "max-response-body-size", valueName: "<size>", desc: "Maximum response body size to read", def: "10000000", kind: kindInt},
	{short: 'e', long: "exclude", valueName: "<pattern>...", desc: "Exclude URLs matched with given regular expressions", kind: kindStringList},
	{short: 'i', long: "include", valueName: "<pattern>...", desc: "Include URLs matched with given regular expressions", kind: kindStringList},
	{long: "follow-robots-txt", desc: "Follow robots.txt when scraping pages", kind: kindBool},
	{long: "follow-sitemap-xml", desc: "Scrape only pages listed in sitemap.xml (deprecated)", kind: kindBool},
	{long: "header", valueName: "<header>...", desc: "Custom headers", kind: kindStringList},
	{short: 'f', long: "ignore-fragments", desc: "Ignore URL fragments", kind: kindBool},
	{long: "max-retries", valueName: "<count>", desc: "Maximum retry count for network errors", def: "0", kind: kindUint},
	{long: "dns-resolver", valueName: "<address>", desc: "Custom DNS resolver", kind: kindString},
	{long: "format", desc: "Output format", def: "text", kind: kindChoice, choices: []string{"text", "json", "junit"}},
	{long: "json", desc: "Output results in JSON (deprecated)", kind: kindBool},
	{long: "experimental-verbose-json", desc: "Include successful results in JSON (deprecated)", kind: kindBool},
	{long: "junit", desc: "Output results as JUnit XML file (deprecated)", kind: kindBool},
	{short: 'r', long: "max-redirections", valueName: "<count>", desc: "Maximum number of redirections", def: "64", kind: kindInt},
	{long: "rate-limit", valueName: "<rate>", desc: "Max requests per second", kind: kindInt},
	{short: 't', long: "timeout", valueName: "<seconds>", desc: "Timeout for HTTP requests in seconds", def: "10", kind: kindInt},
	{short: 'v', long: "verbose", desc: "Show successful results too", kind: kindBool},
	{long: "proxy", valueName: "<host>", desc: "HTTP proxy host", kind: kindString},
	{long: "skip-tls-verification", desc: "Skip TLS certificate verification", kind: kindBool},
	{long: "one-page-only", desc: "Only check links found in the given URL", kind: kindBool},
	{long: "color", desc: "Color output", def: "auto", kind: kindChoice, choices: []string{"auto", "always", "never"}},
	{short: 'h', long: "help", desc: "Show this help", kind: kindBool},
	{long: "version", desc: "Show version", kind: kindBool},
}

func lookupLong(name string) *optionSpec {
	for _, o := range optionSpecs {
		if o.long == name {
			return o
		}
	}
	return nil
}

func lookupShort(c byte) *optionSpec {
	for _, o := range optionSpecs {
		if o.short != 0 && o.short == c {
			return o
		}
	}
	return nil
}

// argumentIsOption reports whether an argument looks like a flag.
func argumentIsOption(arg string) bool {
	if len(arg) > 1 && arg[0] == '-' && arg[1] != '-' {
		return true
	}
	if len(arg) > 2 && arg[0] == '-' && arg[1] == '-' && arg[2] != '-' {
		return true
	}
	return false
}

// parseArguments parses the command line in a go-flags compatible manner.
func parseArguments(args []string) (*arguments, error) {
	a := defaultArguments()

	for i := 0; i < len(args); i++ {
		arg := args[i]

		if arg == "--" {
			a.positional = append(a.positional, args[i+1:]...)
			break
		}

		switch {
		case len(arg) > 2 && arg[0] == '-' && arg[1] == '-' && arg[2] != '-':
			name := arg[2:]
			var value *string
			if pos := strings.Index(name, "="); pos >= 0 {
				v := name[pos+1:]
				value = &v
				name = name[:pos]
			}
			opt := lookupLong(name)
			if opt == nil {
				return nil, fmt.Errorf("unknown flag `%s'", name)
			}
			consumed, err := a.applyOption(opt, true, value, args[i+1:])
			if err != nil {
				return nil, err
			}
			i += consumed
		case len(arg) > 1 && arg[0] == '-' && arg[1] != '-':
			optname := arg[1:]
			var value *string
			if pos := strings.Index(optname, "="); pos == 1 {
				v := optname[2:]
				value = &v
				optname = optname[:1]
			} else if len(optname) > 1 {
				if first := lookupShort(optname[0]); first != nil && first.canArgument() {
					v := optname[1:]
					value = &v
					optname = optname[:1]
				}
			}
			for idx := 0; idx < len(optname); idx++ {
				c := optname[idx]
				opt := lookupShort(c)
				if opt == nil {
					return nil, fmt.Errorf("unknown flag `%c'", c)
				}
				canarg := idx+1 == len(optname)
				consumed, err := a.applyOption(opt, canarg, value, args[i+1:])
				if err != nil {
					return nil, err
				}
				i += consumed
				value = nil
			}
		default:
			a.positional = append(a.positional, arg)
		}
	}

	return a, nil
}

// applyOption sets an option value, possibly consuming the next argument.
func (a *arguments) applyOption(opt *optionSpec, canarg bool, value *string, rest []string) (int, error) {
	if !opt.canArgument() {
		if value != nil {
			return 0, fmt.Errorf("bool flag `%s' cannot have an argument", opt.label())
		}
		a.setBool(opt)
		return 0, nil
	}

	consumed := 0
	var v string
	if value != nil {
		v = *value
	} else if canarg && len(rest) > 0 {
		v = rest[0]
		if argumentIsOption(v) && !(opt.isSignedNumber() && len(v) > 1 && v[0] == '-' && v[1] >= '0' && v[1] <= '9') {
			return 0, fmt.Errorf("expected argument for flag `%s', but got option `%s'", opt.label(), v)
		}
		if v == "--" {
			return 0, fmt.Errorf("expected argument for flag `%s', but got double dash `--'", opt.label())
		}
		consumed = 1
	} else {
		return 0, fmt.Errorf("expected argument for flag `%s'", opt.label())
	}

	if err := a.setValue(opt, v); err != nil {
		return 0, err
	}
	return consumed, nil
}

func (a *arguments) setBool(opt *optionSpec) {
	switch opt.long {
	case "follow-robots-txt":
		a.followRobotsTxt = true
	case "follow-sitemap-xml":
		a.followSitemapXML = true
	case "ignore-fragments":
		a.ignoreFragments = true
	case "json":
		a.jsonOutput = true
	case "experimental-verbose-json":
		a.experimentalVerboseJSON = true
	case "junit":
		a.junitOutput = true
	case "verbose":
		a.verbose = true
	case "skip-tls-verification":
		a.skipTLSVerification = true
	case "one-page-only":
		a.onePageOnly = true
	case "help":
		a.help = true
	case "version":
		a.version = true
	}
}

func (a *arguments) setValue(opt *optionSpec, v string) error {
	switch opt.kind {
	case kindInt:
		n, err := strconv.ParseInt(v, 0, 64)
		if err != nil {
			return fmt.Errorf("invalid argument for flag `%s' (expected int): %s", opt.label(), err.Error())
		}
		switch opt.long {
		case "buffer-size":
			a.bufferSize = int(n)
		case "max-connections":
			a.maxConnections = int(n)
		case "max-connections-per-host":
			a.maxConnectionsPerHost = int(n)
		case "max-response-body-size":
			a.maxResponseBodySize = int(n)
		case "max-redirections":
			a.maxRedirections = int(n)
		case "rate-limit":
			a.rateLimit = int(n)
		case "timeout":
			a.timeout = int(n)
		}
	case kindUint:
		n, err := strconv.ParseUint(v, 0, 64)
		if err != nil {
			return fmt.Errorf("invalid argument for flag `%s' (expected uint): %s", opt.label(), err.Error())
		}
		if opt.long == "max-retries" {
			a.maxRetries = uint(n)
		}
	case kindString:
		switch opt.long {
		case "accepted-status-codes":
			a.acceptedStatusCodes = v
		case "dns-resolver":
			a.dnsResolver = v
		case "proxy":
			a.proxy = v
		}
	case kindStringList:
		switch opt.long {
		case "exclude":
			a.excludes = append(a.excludes, v)
		case "include":
			a.includes = append(a.includes, v)
		case "header":
			a.headers = append(a.headers, v)
		}
	case kindChoice:
		found := false
		for _, c := range opt.choices {
			if c == v {
				found = true
				break
			}
		}
		if !found {
			allowed := strings.Join(opt.choices[:len(opt.choices)-1], ", ") + " or " + opt.choices[len(opt.choices)-1]
			return fmt.Errorf("Invalid value `%s' for option `%s'. Allowed values are: %s", v, opt.label(), allowed)
		}
		switch opt.long {
		case "format":
			a.format = v
		case "color":
			a.color = v
		}
	}
	return nil
}

var errInvalidArgumentCount = errors.New("invalid number of arguments")
EOF
echo done"}

