func lookupLong(name string) *optionSpec {
	for _, o := range optionSpecs {
		if o.long == name {
			return o
		}
	}
	return nil
}

func lookupShort(c byte) *optionSpec {
	for _, o := range optionSpecs {
		if o.short != 0 && o.short == c {
			return o
		}
	}
	return nil
}

// argumentIsOption reports whether an argument looks like a flag.
func argumentIsOption(arg string) bool {
	if len(arg) > 1 && arg[0] == '-' && arg[1] != '-' {
		return true
	}
	if len(arg) > 2 && arg[0] == '-' && arg[1] == '-' && arg[2] != '-' {
		return true
	}
	return false
}

// parseArguments parses the command line in a go-flags compatible manner.
func parseArguments(args []string) (*arguments, error) {
	a := defaultArguments()

	for i := 0; i < len(args); i++ {
		arg := args[i]

		if arg == "--" {
			a.positional = append(a.positional, args[i+1:]...)
			break
		}

		switch {
		case len(arg) > 2 && arg[0] == '-' && arg[1] == '-' && arg[2] != '-':
			name := arg[2:]
			var value *string
			if pos := strings.Index(name, "="); pos >= 0 {
				v := name[pos+1:]
				value = &v
				name = name[:pos]
			}
			opt := lookupLong(name)
			if opt == nil {
				return nil, fmt.Errorf("unknown flag `%s'", name)
			}
			consumed, err := a.applyOption(opt, true, value, args[i+1:])
			if err != nil {
				return nil, err
			}
			i += consumed
		case len(arg) > 1 && arg[0] == '-' && arg[1] != '-':
			optname := arg[1:]
			var value *string
			if pos := strings.Index(optname, "="); pos == 1 {
				v := optname[2:]
				value = &v
				optname = optname[:1]
			} else if len(optname) > 1 {
				if first := lookupShort(optname[0]); first != nil && first.canArgument() {
					v := optname[1:]
					value = &v
					optname = optname[:1]
				}
			}
			for idx := 0; idx < len(optname); idx++ {
				c := optname[idx]
				opt := lookupShort(c)
				if opt == nil {
					return nil, fmt.Errorf("unknown flag `%c'", c)
				}
				canarg := idx+1 == len(optname)
				consumed, err := a.applyOption(opt, canarg, value, args[i+1:])
				if err != nil {
					return nil, err
				}
				i += consumed
				value = nil
			}
		default:
			a.positional = append(a.positional, arg)
		}
	}

	return a, nil
}

// applyOption sets an option value, possibly consuming the next argument.
func (a *arguments) applyOption(opt *optionSpec, canarg bool, value *string, rest []string) (int, error) {
	if !opt.canArgument() {
		if value != nil {
			return 0, fmt.Errorf("bool flag `%s' cannot have an argument", opt.label())
		}
		a.setBool(opt)
		return 0, nil
	}

	consumed := 0
	var v string
	if value != nil {
		v = *value
	} else if canarg && len(rest) > 0 {
		v = rest[0]
		if argumentIsOption(v) && !(opt.isSignedNumber() && len(v) > 1 && v[0] == '-' && v[1] >= '0' && v[1] <= '9') {
			return 0, fmt.Errorf("expected argument for flag `%s', but got option `%s'", opt.label(), v)
		}
		if v == "--" {
			return 0, fmt.Errorf("expected argument for flag `%s', but got double dash `--'", opt.label())
		}
		consumed = 1
	} else {
		return 0, fmt.Errorf("expected argument for flag `%s'", opt.label())
	}

	if err := a.setValue(opt, v); err != nil {
		return 0, err
	}
	return consumed, nil
}

func (a *arguments) setBool(opt *optionSpec) {
	switch opt.long {
	case "follow-robots-txt":
		a.followRobotsTxt = true
	case "follow-sitemap-xml":
		a.followSitemapXML = true
	case "ignore-fragments":
		a.ignoreFragments = true
	case "json":
		a.jsonOutput = true
	case "experimental-verbose-json":
		a.experimentalVerboseJSON = true
	case "junit":
		a.junitOutput = true
	case "verbose":
		a.verbose = true
	case "skip-tls-verification":
		a.skipTLSVerification = true
	case "one-page-only":
		a.onePageOnly = true
	case "help":
		a.help = true
	case "version":
		a.version = true
	}
}

func (a *arguments) setValue(opt *optionSpec, v string) error {
	switch opt.kind {
	case kindInt:
		n, err := strconv.ParseInt(v, 0, 64)
		if err != nil {
			return fmt.Errorf("invalid argument for flag `%s' (expected int): %s", opt.label(), err.Error())
		}
		switch opt.long {
		case "buffer-size":
			a.bufferSize = int(n)
		case "max-connections":
			a.maxConnections = int(n)
		case "max-connections-per-host":
			a.maxConnectionsPerHost = int(n)
		case "max-response-body-size":
			a.maxResponseBodySize = int(n)
		case "max-redirections":
			a.maxRedirections = int(n)
		case "rate-limit":
			a.rateLimit = int(n)
		case "timeout":
			a.timeout = int(n)
		}
	case kindUint:
		n, err := strconv.ParseUint(v, 0, 64)
		if err != nil {
			return fmt.Errorf("invalid argument for flag `%s' (expected uint): %s", opt.label(), err.Error())
		}
		if opt.long == "max-retries" {
			a.maxRetries = uint(n)
		}
	case kindString:
		switch opt.long {
		case "accepted-status-codes":
			a.acceptedStatusCodes = v
		case "dns-resolver":
			a.dnsResolver = v
		case "proxy":
			a.proxy = v
		}
	case kindStringList:
		switch opt.long {
		case "exclude":
			a.excludes = append(a.excludes, v)
		case "include":
			a.includes = append(a.includes, v)
		case "header":
			a.headers = append(a.headers, v)
		}
	case kindChoice:
		found := false
		for _, c := range opt.choices {
			if c == v {
				found = true
				break
			}
		}
		if !found {
			allowed := strings.Join(opt.choices[:len(opt.choices)-1], ", ") + " or " + opt.choices[len(opt.choices)-1]
			return fmt.Errorf("Invalid value `%s' for option `%s'. Allowed values are: %s", v, opt.label(), allowed)
		}
		switch opt.long {
		case "format":
			a.format = v
		case "color":
			a.color = v
		}
	}
	return nil
}

var errInvalidArgumentCount = errors.New("invalid number of arguments")
EOF
echo done

