// wrapText wraps s at spaces so that each line fits in l columns.
func wrapText(s string, l int, prefix string) string {
	var ret string

	if l < 10 {
		l = 10
	}

	lines := strings.Split(s, "\n")

	for _, line := range lines {
		var retline string

		line = strings.TrimSpace(line)

		for len(line) > l {
			suffix := ""

			pos := strings.LastIndex(line[:l], " ")

			if pos < 0 {
				pos = l - 1
				suffix = "-\n"
			}

			if len(retline) != 0 {
				retline += "\n" + prefix
			}

			retline += strings.TrimSpace(line[:pos]) + suffix
			line = strings.TrimSpace(line[pos:])
		}

		if len(line) > 0 {
			if len(retline) != 0 {
				retline += "\n" + prefix
			}

			retline += line
		}

		if len(ret) > 0 {
			ret += "\n"

			if len(retline) > 0 {
				ret += prefix
			}
		}

		ret += retline
	}

	return ret
}

func descriptionStart() int {
	maxLongLen := 0
	hasShort := false
	hasValueName := false
	for _, o := range optionSpecs {
		if o.short != 0 {
			hasShort = true
		}
		if o.valueName != "" {
			hasValueName = true
		}
		l := len(o.long) + len(o.valueName)
		if o.valueName == "" && len(o.choices) > 0 {
			l += len("[" + strings.Join(o.choices, "|") + "]")
		}
		if l > maxLongLen {
			maxLongLen = l
		}
	}

	start := maxLongLen + distanceBetweenOptionAndDescription
	if hasShort {
		start += 2
	}
	if maxLongLen > 0 {
		start += 4
	}
	if hasValueName {
		start += 3
	}
	return start
}

// writeHelp prints the usage text in the style of go-flags.
func writeHelp(w io.Writer, name string) {
	columns := terminalColumns()
	if columns <= 0 {
		columns = 80
	}

	fmt.Fprintf(w, "Usage:\n  %s [options] <url>\n\nApplication Options:\n", name)

	descstart := descriptionStart() + paddingBeforeOption

	for _, o := range optionSpecs {
		line := strings.Repeat(" ", paddingBeforeOption)
		if o.short != 0 {
			line += "-" + string(o.short)
		} else {
			line += "  "
		}
		if o.short != 0 {
			line += ", "
		} else {
			line += "  "
		}
		line += "--" + o.long
		if o.canArgument() {
			line += "="
			if o.valueName != "" {
				line += o.valueName
			} else if len(o.choices) > 0 {
				line += "[" + strings.Join(o.choices, "|") + "]"
			}
		}

		written := len(line)
		io.WriteString(w, line)

		if o.desc != "" {
			io.WriteString(w, strings.Repeat(" ", descstart-written))
			desc := o.desc
			if o.def != "" {
				desc = fmt.Sprintf("%s (default: %v)", o.desc, o.def)
			}
			io.WriteString(w, wrapText(desc, columns-descstart, strings.Repeat(" ", descstart)))
		}
		io.WriteString(w, "\n")
	}
}
EOF
echo done"}

