package main

import (
	"bufio"
	"bytes"
	"compress/gzip"
	"compress/zlib"
	"context"
	"crypto/tls"
	"encoding/base64"
	"errors"
	"fmt"
	"io"
	"net"
	"net/url"
	"os"
	"strconv"
	"strings"
	"sync"
	"sync/atomic"
	"time"
)

const (
	defaultMaxAttempts = 5
	minReadBufferSize  = 16
	dnsCacheDuration   = time.Minute
)

var (
	errTimeout          = errors.New("timeout")
	errDialTimeout      = errors.New("dialing to the given TCP address timed out")
	errConnectionClosed = errors.New("the server closed connection before returning the first response byte. Make sure the server returns 'Connection: close' response header before closing the connection")
	errBodyTooLarge     = errors.New("body size exceeds the given limit")
	errNeedMore         = errors.New("need more data: cannot find trailing lf")
	errSmallBuffer      = errors.New("small read buffer. Increase ReadBufferSize")
	errEmptyInt         = errors.New("empty integer")
	errUnexpectedChar   = errors.New("unexpected first char found. Expecting 0-9")
	errTooLargeInt      = errors.New("too large integer")
	errEmptyHexNum      = errors.New("empty hex number")
	errTooLargeHexNum   = errors.New("too large hex number")
)

// dialUpstreamError annotates a dial failure with the resolved address.
type dialUpstreamError struct {
	upstream string
	err      error
}

func (e *dialUpstreamError) Error() string {
	return fmt.Sprintf("error when dialing %s: %s", e.upstream, e.err.Error())
}

func (e *dialUpstreamError) Unwrap() error {
	return e.err
}

// rawResponse is the result of a single HTTP exchange.
type rawResponse struct {
	StatusCode int
	Headers    []headerPair
	Body       []byte
}

type headerPair struct {
	Key   string
	Value string
}

// header returns the last value of a header (case-insensitively).
func (r *rawResponse) header(name string) string {
	v := ""
	for _, h := range r.Headers {
		if strings.EqualFold(h.Key, name) {
			v = h.Value
		}
	}
	return v
}

// requestHeader is a user supplied header after normalisation.
type requestHeader struct {
	Key   string
	Value string
}

type transport struct {
	timeout      time.Duration
	bufferSize   int
	maxBodySize  int
	skipTLS      bool
	proxy        *proxyConfig
	resolver     *net.Resolver
	dnsCache     sync.Map
	proxyDialer  *tcpDialer
	targetDialer *tcpDialer
}

type proxyConfig struct {
	addr string
	auth string
}

func newTransport(timeout time.Duration, bufferSize, maxBodySize int, skipTLS bool, proxy string, dnsResolver string) *transport {
	resolver := net.DefaultResolver
	if dnsResolver != "" {
		resolver = &net.Resolver{
			PreferGo: true,
			Dial: func(ctx context.Context, network, _ string) (net.Conn, error) {
				d := net.Dialer{}
				return d.DialContext(ctx, network, dnsResolver)
			},
		}
	}

	t := &transport{
		timeout:     timeout,
		bufferSize:  bufferSize,
		maxBodySize: maxBodySize,
		skipTLS:     skipTLS,
		resolver:    resolver,
	}
	t.targetDialer = &tcpDialer{resolver: resolver, dualStack: true}
	t.proxyDialer = &tcpDialer{resolver: net.DefaultResolver, dualStack: false}

	if proxy != "" {
		t.proxy = parseProxy(proxy)
	}

	return t
}

func parseProxy(s string) *proxyConfig {
	c := &proxyConfig{}
	if strings.Contains(s, "://") {
		if u, err := url.Parse(s); err == nil {
			c.addr = u.Host
			if u.User != nil {
				c.auth = base64.StdEncoding.EncodeToString([]byte(u.User.String()))
			}
			return c
		}
	}
	if i := strings.LastIndex(s, "@"); i >= 0 {
		c.auth = base64.StdEncoding.EncodeToString([]byte(s[:i]))
		s = s[i+1:]
	}
	c.addr = s
	return c
}

// addMissingPort appends the default port to an address without one.
func addMissingPort(addr string, isTLS bool) string {
	addrLen := len(addr)
	if addrLen == 0 {
		return addr
	}

	if addr[0] == '[' {
		if addr[addrLen-1] != ']' {
			return addr
		}
	} else if strings.LastIndexByte(addr, ':') > 0 {
		return addr
	}

	port := ":80"
	if isTLS {
		port = ":443"
	}
	return addr + port
}

func tlsServerName(addr string) string {
	if !strings.Contains(addr, ":") {
		return addr
	}
	host, _, err := net.SplitHostPort(addr)
	if err != nil {
		return "*"
	}
	return host
}

// requestURI builds the request target the way the original client does.
func requestURI(u *url.URL) string {
	path := u.EscapedPath()
	if path != "" && path[0] != '/' && u.Host != "" {
		path = "/" + path
	}
	if u.RawQuery != "" {
		path += "?" + u.RawQuery
	}
	if path == "" {
		path = "/"
	}
	return path
}

// normalizedURL returns the canonical page URL for a request URL.
func normalizedURL(u *url.URL) string {
	return strings.ToLower(u.Scheme) + "://" + strings.ToLower(u.Host) + requestURI(u)
}

func isTimeoutError(err error) bool {
	if err == nil {
		return false
	}
	if errors.Is(err, os.ErrDeadlineExceeded) {
		return true
	}
	var ne net.Error
	if errors.As(err, &ne) && ne.Timeout() {
		return true
	}
	return false
}

// Get performs a GET request against u.
func (t *transport) Get(u *url.URL, headers []requestHeader) (*rawResponse, error) {
	if t.timeout <= 0 {
		return nil, errTimeout
	}
	deadline := time.Now().Add(t.timeout)

	scheme := strings.ToLower(u.Scheme)
	isTLS := scheme == "https"
	if scheme != "http" && !isTLS {
		return nil, fmt.Errorf("unsupported protocol %q. http and https are supported", scheme)
	}

	host := strings.ToLower(u.Host)
	addr := addMissingPort(host, isTLS)
	req := t.buildRequest(u, host, headers)

	var err error
	for attempt := 0; attempt < defaultMaxAttempts; attempt++ {
		if time.Now().After(deadline) {
			return nil, errTimeout
		}
		var resp *rawResponse
		var retry bool
		resp, retry, err = t.do(addr, host, isTLS, req, deadline)
		if err == nil {
			return resp, nil
		}
		if !retry {
			break
		}
	}
	if err == io.EOF {
		err = errConnectionClosed
	}
	return nil, err
}

func (t *transport) buildRequest(u *url.URL, host string, headers []requestHeader) []byte {
	var b bytes.Buffer
	b.WriteString("GET ")
	b.WriteString(requestURI(u))
	b.WriteString(" HTTP/1.1\r\n")

	userAgent := ""
	connectionClose := true
	hasAccept := false
	hasAuthorization := false
	var others []requestHeader
	for _, h := range headers {
		switch {
		case strings.EqualFold(h.Key, "User-Agent"):
			userAgent = h.Value
		case strings.EqualFold(h.Key, "Host"):
			// The host header always follows the request URL.
		case strings.EqualFold(h.Key, "Transfer-Encoding"):
			// Managed automatically.
		case strings.EqualFold(h.Key, "Connection"):
			if h.Value == "close" {
				connectionClose = true
			} else {
				connectionClose = false
				others = append(others, h)
			}
		default:
			if strings.EqualFold(h.Key, "Accept") {
				hasAccept = true
			}
			if strings.EqualFold(h.Key, "Authorization") {
				hasAuthorization = true
			}
			others = append(others, h)
		}
	}

	if userAgent != "" {
		b.WriteString("User-Agent: " + userAgent + "\r\n")
	}
	b.WriteString("Host: " + host + "\r\n")

	authorization := ""
	if u.User != nil && u.User.Username() != "" {
		password, _ := u.User.Password()
		authorization = "Basic " + base64.StdEncoding.EncodeToString([]byte(u.User.Username()+":"+password))
	}

	for _, h := range others {
		if authorization != "" && strings.EqualFold(h.Key, "Authorization") {
			b.WriteString(h.Key + ": " + authorization + "\r\n")
			continue
		}
		b.WriteString(h.Key + ": " + h.Value + "\r\n")
	}
	if !hasAccept {
		b.WriteString("Accept: */*\r\n")
	}
	if authorization != "" && !hasAuthorization {
		b.WriteString("Authorization: " + authorization + "\r\n")
	}
	if connectionClose {
		b.WriteString("Connection: close\r\n")
	}
	b.WriteString("\r\n")
	return b.Bytes()
}

// do performs one attempt. The returned bool tells whether retrying makes sense.
func (t *transport) do(addr, host string, isTLS bool, req []byte, deadline time.Time) (*rawResponse, bool, error) {
	conn, err := t.dial(addr, deadline)
	if err != nil {
		return nil, false, err
	}
	defer conn.Close()

	if err := conn.SetDeadline(deadline); err != nil {
		return nil, false, err
	}

	if isTLS {
		cfg := &tls.Config{InsecureSkipVerify: t.skipTLS}
		serverName := tlsServerName(addr)
		if serverName == "*" {
			cfg.InsecureSkipVerify = true
		} else {
			cfg.ServerName = serverName
		}
		tlsConn := tls.Client(conn, cfg)
		if err := tlsConn.Handshake(); err != nil {
			if isTimeoutError(err) {
				return nil, false, errTimeout
			}
			return nil, true, err
		}
		conn = tlsConn
	}

	if _, err := conn.Write(req); err != nil {
		if isTimeoutError(err) {
			return nil, false, errTimeout
		}
		return nil, true, err
	}

	size := t.bufferSize
	if size <= 0 {
		size = 4096
	}
	br := bufio.NewReaderSize(conn, size)

	resp, err := readResponse(br, t.maxBodySize)
	if err != nil {
		if isTimeoutError(err) {
			return nil, false, errTimeout
		}
		if err == errBodyTooLarge {
			return nil, false, err
		}
		return nil, true, err
	}

	return resp, false, nil
}

// dial opens a TCP connection, going through the proxy when configured.
func (t *transport) dial(addr string, deadline time.Time) (net.Conn, error) {
	if t.proxy == nil {
		return t.targetDialer.dial(addr, deadline)
	}

	conn, err := t.proxyDialer.dial(t.proxy.addr, deadline)
	if err != nil {
		return nil, err
	}
	conn.SetDeadline(deadline)

	req := "CONNECT " + addr + " HTTP/1.1\r\nHost: " + addr + "\r\n"
	if t.proxy.auth != "" {
		req += "Proxy-Authorization: Basic " + t.proxy.auth + "\r\n"
	}
	req += "\r\n"
	if _, err := conn.Write([]byte(req)); err != nil {
		conn.Close()
		return nil, err
	}

	br := bufio.NewReaderSize(conn, 4096)
	status, _, _, err := readHeaders(br)
	if err != nil {
		conn.Close()
		if err == io.EOF {
			return nil, errConnectionClosed
		}
		return nil, err
	}
	if status != 200 {
		conn.Close()
		return nil, fmt.Errorf("could not connect to proxyAddr: %s status code: %d", t.proxy.addr, status)
	}
	conn.SetDeadline(time.Time{})
	return conn, nil
}

// tcpDialer resolves and dials addresses, rotating through resolved IPs.
type tcpDialer struct {
	resolver  *net.Resolver
	dualStack bool
	cache     sync.Map
}

type tcpAddrEntry struct {
	addrs       []net.TCPAddr
	addrsIdx    uint32
	resolveTime time.Time
}

func (d *tcpDialer) dial(addr string, deadline time.Time) (net.Conn, error) {
	addrs, idx, err := d.getTCPAddrs(addr, deadline)
	if err != nil {
		return nil, err
	}

	network := "tcp4"
	if d.dualStack {
		network = "tcp"
	}

	var conn net.Conn
	n := uint32(len(addrs))
	for n > 0 {
		conn, err = d.tryDial(network, &addrs[idx%n], deadline)
		if err == nil {
			return conn, nil
		}
		if errors.Is(err, errDialTimeout) {
			return nil, err
		}
		idx++
		n--
	}
	return nil, err
}

func (d *tcpDialer) tryDial(network string, addr *net.TCPAddr, deadline time.Time) (net.Conn, error) {
	ctx, cancel := context.WithDeadline(context.Background(), deadline)
	defer cancel()

	dialer := net.Dialer{}
	conn, err := dialer.DialContext(ctx, network, addr.String())
	if err != nil {
		if ctx.Err() == context.DeadlineExceeded {
			return nil, &dialUpstreamError{upstream: addr.String(), err: errDialTimeout}
		}
		return nil, &dialUpstreamError{upstream: addr.String(), err: err}
	}
	return conn, nil
}

func (d *tcpDialer) getTCPAddrs(addr string, deadline time.Time) ([]net.TCPAddr, uint32, error) {
	var e *tcpAddrEntry
	if v, ok := d.cache.Load(addr); ok {
		e = v.(*tcpAddrEntry)
		if time.Since(e.resolveTime) > dnsCacheDuration {
			e = nil
		}
	}

	if e == nil {
		addrs, err := d.resolveTCPAddrs(addr, deadline)
		if err != nil {
			return nil, 0, err
		}
		e = &tcpAddrEntry{addrs: addrs, resolveTime: time.Now()}
		d.cache.Store(addr, e)
	}

	idx := atomic.AddUint32(&e.addrsIdx, 1)
	return e.addrs, idx, nil
}

func (d *tcpDialer) resolveTCPAddrs(addr string, deadline time.Time) ([]net.TCPAddr, error) {
	host, portS, err := net.SplitHostPort(addr)
	if err != nil {
		return nil, err
	}
	port, err := strconv.Atoi(portS)
	if err != nil {
		return nil, err
	}

	ctx, cancel := context.WithDeadline(context.Background(), deadline)
	defer cancel()

	ipaddrs, err := d.resolver.LookupIPAddr(ctx, host)
	if err != nil {
		return nil, err
	}

	addrs := make([]net.TCPAddr, 0, len(ipaddrs))
	for _, ip := range ipaddrs {
		if !d.dualStack && ip.IP.To4() == nil {
			continue
		}
		addrs = append(addrs, net.TCPAddr{IP: ip.IP, Port: port, Zone: ip.Zone})
	}
	if len(addrs) == 0 {
		return nil, fmt.Errorf("couldn't find DNS entries for the given domain. Try using DialDualStack")
	}
	return addrs, nil
}

// readResponse parses a full HTTP response from br.
func readResponse(br *bufio.Reader, maxBodySize int) (*rawResponse, error) {
	status, headers, contentLength, err := readHeaders(br)
	if err != nil {
		return nil, err
	}

	resp := &rawResponse{StatusCode: status, Headers: headers}

	skipBody := status == 204 || status == 304 || (status >= 100 && status < 200)
	if !skipBody {
		body, err := readBody(br, contentLength, maxBodySize)
		if err != nil {
			return nil, err
		}
		resp.Body = body
	}

	switch resp.header("Content-Encoding") {
	case "gzip":
		r, err := gzip.NewReader(bytes.NewReader(resp.Body))
		if err != nil {
			return nil, err
		}
		b, err := io.ReadAll(r)
		if err != nil {
			return nil, err
		}
		resp.Body = b
	case "deflate":
		r, err := zlib.NewReader(bytes.NewReader(resp.Body))
		if err != nil {
			return nil, err
		}
		b, err := io.ReadAll(r)
		if err != nil {
			return nil, err
		}
		resp.Body = b
	}

	return resp, nil
}

// readHeaders reads the status line and headers. contentLength is -1 for
// chunked encoding and -2 when the body extends until the connection closes.
func readHeaders(br *bufio.Reader) (int, []headerPair, int, error) {
	n := 1
	for {
		b, err := br.Peek(n)
		if len(b) == 0 {
			if isTimeoutError(err) {
				return 0, nil, 0, errTimeout
			}
			if n == 1 || err == io.EOF {
				return 0, nil, 0, io.EOF
			}
			if err == bufio.ErrBufferFull {
				return 0, nil, 0, fmt.Errorf("error when reading response headers: %w", errNeedMore)
			}
			return 0, nil, 0, fmt.Errorf("error when reading response headers: %w", err)
		}

		b, _ = br.Peek(br.Buffered())
		status, headers, contentLength, headersLen, parseErr := parseHeaders(b)
		if parseErr == nil {
			br.Discard(headersLen)
			return status, headers, contentLength, nil
		}

		if parseErr != errNeedMore {
			return 0, nil, 0, headerErrorMsg(parseErr, b)
		}
		if err == nil {
			n = br.Buffered() + 1
			continue
		}
		if isOnlyCRLF(b) {
			return 0, nil, 0, io.EOF
		}
		if isTimeoutError(err) {
			return 0, nil, 0, errTimeout
		}
		if err != bufio.ErrBufferFull {
			return 0, nil, 0, headerErrorMsg(err, b)
		}
		return 0, nil, 0, headerErrorMsg(errSmallBuffer, b)
	}
}

func isOnlyCRLF(b []byte) bool {
	for _, ch := range b {
		if ch != '\r' && ch != '\n' {
			return false
		}
	}
	return true
}

func headerErrorMsg(err error, b []byte) error {
	return fmt.Errorf("error when reading response headers: %w. Buffer size=%d, contents: %s", err, len(b), bufferSnippet(b))
}

func bufferSnippet(b []byte) string {
	n := len(b)
	start := 200
	end := n - start
	if start >= end {
		start = n
		end = n
	}
	bStart, bEnd := b[:start], b[end:]
	if len(bEnd) == 0 {
		return fmt.Sprintf("%q", b)
	}
	return fmt.Sprintf("%q...%q", bStart, bEnd)
}

// nextLine splits off the first CRLF terminated line.
func nextLine(b []byte) ([]byte, []byte, error) {
	n := bytes.Index(b, []byte("\r\n"))
	if n < 0 {
		return nil, nil, errNeedMore
	}
	return b[:n], b[n+2:], nil
}

func parseUintBuf(b []byte) (int, int, error) {
	n := len(b)
	if n == 0 {
		return -1, 0, errEmptyInt
	}
	v := 0
	for i := 0; i < n; i++ {
		c := b[i]
		k := c - '0'
		if k > 9 {
			if i == 0 {
				return -1, i, errUnexpectedChar
			}
			return v, i, nil
		}
		vNew := 10*v + int(k)
		if vNew < v {
			return -1, i, errTooLargeInt
		}
		v = vNew
	}
	return v, n, nil
}

func parseContentLength(b []byte) (int, error) {
	v, n, err := parseUintBuf(b)
	if err != nil {
		return -1, fmt.Errorf("cannot parse Content-Length: %w", err)
	}
	if n != len(b) {
		return -1, fmt.Errorf("cannot parse Content-Length: %w", errors.New("non-numeric chars at the end of Content-Length"))
	}
	return v, nil
}

// parseHeaders parses the status line and header block held in buf.
func parseHeaders(buf []byte) (int, []headerPair, int, int, error) {
	bNext := buf
	var line []byte
	var err error
	for len(line) == 0 {
		if line, bNext, err = nextLine(bNext); err != nil {
			return 0, nil, 0, 0, err
		}
	}

	n := bytes.IndexByte(line, ' ')
	if n < 0 {
		return 0, nil, 0, 0, fmt.Errorf("cannot find whitespace in the first line of response %q", buf)
	}
	line = line[n+1:]

	status, n, err := parseUintBuf(line)
	if err != nil {
		return 0, nil, 0, 0, fmt.Errorf("cannot parse response status code: %w. Response %q", err, buf)
	}
	if len(line) > n && line[n] != ' ' {
		return 0, nil, 0, 0, fmt.Errorf("unexpected char at the end of status code. Response %q", buf)
	}

	contentLength := -2
	var headers []headerPair
	for {
		var hline []byte
		hline, bNext, err = nextLine(bNext)
		if err != nil {
			return 0, nil, 0, 0, err
		}
		if len(hline) == 0 {
			break
		}
		colon := bytes.IndexByte(hline, ':')
		if colon < 0 {
			return 0, nil, 0, 0, errNeedMore
		}
		key := string(hline[:colon])
		value := hline[colon+1:]
		for len(value) > 0 && value[0] == ' ' {
			value = value[1:]
		}
		for len(value) > 0 && (value[len(value)-1] == ' ' || value[len(value)-1] == '\t') {
			value = value[:len(value)-1]
		}

		switch {
		case strings.EqualFold(key, "Content-Length"):
			if contentLength != -1 {
				contentLength, err = parseContentLength(value)
				if err != nil {
					return 0, nil, 0, 0, err
				}
			}
			continue
		case strings.EqualFold(key, "Transfer-Encoding"):
			if !bytes.Equal(value, []byte("identity")) {
				contentLength = -1
			}
			continue
		}
		headers = append(headers, headerPair{Key: key, Value: string(value)})
	}

	return status, headers, contentLength, len(buf) - len(bNext), nil
}

// readBody reads the response body according to contentLength.
func readBody(br *bufio.Reader, contentLength int, maxBodySize int) ([]byte, error) {
	switch {
	case contentLength >= 0:
		if maxBodySize > 0 && contentLength > maxBodySize {
			return nil, errBodyTooLarge
		}
		body := make([]byte, contentLength)
		if _, err := io.ReadFull(br, body); err != nil {
			if err == io.EOF {
				err = io.ErrUnexpectedEOF
			}
			return nil, err
		}
		return body, nil
	case contentLength == -1:
		return readChunkedBody(br, maxBodySize)
	default:
		var body []byte
		buf := make([]byte, 4096)
		for {
			n, err := br.Read(buf)
			body = append(body, buf[:n]...)
			if maxBodySize > 0 && len(body) > maxBodySize {
				return nil, errBodyTooLarge
			}
			if err != nil {
				if err == io.EOF {
					return body, nil
				}
				return nil, err
			}
		}
	}
}

func readHexInt(br *bufio.Reader) (int, error) {
	n := 0
	i := 0
	for {
		c, err := br.ReadByte()
		if err != nil {
			if err == io.EOF && i > 0 {
				return n, nil
			}
			return -1, err
		}
		k := int(hex2intTable[c])
		if k == 16 {
			if i == 0 {
				return -1, errEmptyHexNum
			}
			if err := br.UnreadByte(); err != nil {
				return -1, err
			}
			return n, nil
		}
		if i >= 16 {
			return -1, errTooLargeHexNum
		}
		n = (n << 4) | k
		i++
	}
}

var hex2intTable = func() [256]byte {
	var t [256]byte
	for i := range t {
		t[i] = 16
	}
	for c := '0'; c <= '9'; c++ {
		t[c] = byte(c - '0')
	}
	for c := 'a'; c <= 'f'; c++ {
		t[c] = byte(c-'a') + 10
	}
	for c := 'A'; c <= 'F'; c++ {
		t[c] = byte(c-'A') + 10
	}
	return t
}()

func readCRLF(br *bufio.Reader) error {
	for _, exp := range []byte("\r\n") {
		c, err := br.ReadByte()
		if err != nil {
			return fmt.Errorf("cannot read %q char at the end of chunk size: %w", exp, err)
		}
		if c != exp {
			return fmt.Errorf("unexpected char %q at the end of chunk size. Expected %q", c, exp)
		}
	}
	return nil
}

func parseChunkSize(br *bufio.Reader) (int, error) {
	n, err := readHexInt(br)
	if err != nil {
		return -1, err
	}
	for {
		c, err := br.ReadByte()
		if err != nil {
			return -1, fmt.Errorf("cannot read '\r' char at the end of chunk size: %w", err)
		}
		if c != '\r' {
			continue
		}
		if err := br.UnreadByte(); err != nil {
			return -1, fmt.Errorf("cannot unread '\r' char at the end of chunk size: %w", err)
		}
		break
	}
	if err := readCRLF(br); err != nil {
		return -1, err
	}
	return n, nil
}

func readChunkedBody(br *bufio.Reader, maxBodySize int) ([]byte, error) {
	var body []byte
	for {
		chunkSize, err := parseChunkSize(br)
		if err != nil {
			return nil, err
		}
		if chunkSize == 0 {
			// Consume the trailer section.
			for {
				line, err := br.ReadSlice('\n')
				if err != nil {
					if err == io.EOF {
						return body, nil
					}
					return nil, err
				}
				if len(bytes.TrimRight(line, "\r\n")) == 0 {
					return body, nil
				}
			}
		}
		if maxBodySize > 0 && len(body)+chunkSize > maxBodySize {
			return nil, errBodyTooLarge
		}
		chunk := make([]byte, chunkSize+2)
		if _, err := io.ReadFull(br, chunk); err != nil {
			if err == io.EOF {
				err = io.ErrUnexpectedEOF
			}
			return nil, err
		}
		if !bytes.Equal(chunk[chunkSize:], []byte("\r\n")) {
			return nil, errors.New("cannot find crlf at the end of chunk")
		}
		body = append(body, chunk[:chunkSize]...)
	}
}
