func walkNodes(n *html.Node, f func(*html.Node)) {
	if n == nil {
		return
	}
	f(n)
	for c := n.FirstChild; c != nil; c = c.NextSibling {
		walkNodes(c, f)
	}
}

// fetchResult is a cached result of fetching a URL without its fragment.
type fetchResult struct {
	status int
	page   *page
	err    error
	done   chan struct{}
}

// linkFetcher fetches links, caching responses by URL.
type linkFetcher struct {
	client          httpClient
	headers         []requestHeader
	ignoreFragments bool
	cache           sync.Map
}

func newLinkFetcher(client httpClient, headers []requestHeader, ignoreFragments bool) *linkFetcher {
	return &linkFetcher{client: client, headers: headers, ignoreFragments: ignoreFragments}
}

// Fetch retrieves a URL and validates its fragment when applicable.
func (f *linkFetcher) Fetch(rawURL string) (int, *page, error) {
	u, err := url.Parse(rawURL)
	if err != nil {
		return 0, nil, err
	}

	fragment := u.Fragment
	u.Fragment = ""
	u.RawFragment = ""

	r := f.sendRequestWithCache(u)
	if r.err != nil {
		return 0, nil, r.err
	}

	if r.page != nil && fragment != "" && !f.ignoreFragments && !strings.HasPrefix(fragment, ":~:") {
		if !r.page.hasID(fragment) {
			return 0, nil, fmt.Errorf("id #%v not found", fragment)
		}
	}

	return r.status, r.page, nil
}

func (f *linkFetcher) sendRequestWithCache(u *url.URL) *fetchResult {
	key := u.String()

	r := &fetchResult{done: make(chan struct{})}
	if v, loaded := f.cache.LoadOrStore(key, r); loaded {
		r = v.(*fetchResult)
		<-r.done
		return r
	}

	r.status, r.page, r.err = f.sendRequest(u)
	close(r.done)
	return r
}

func (f *linkFetcher) sendRequest(u *url.URL) (int, *page, error) {
	r, err := f.client.Get(u, f.headers)
	if err != nil {
		return 0, nil, err
	}

	contentType := r.Header("Content-Type")
	if contentType == "" {
		return r.StatusCode, nil, nil
	}

	mediaType, _, err := mime.ParseMediaType(contentType)
	if err != nil {
		return 0, nil, err
	}
	if mediaType != "text/html" {
		return r.StatusCode, nil, nil
	}

