package main

import (
	"net/url"
	"regexp"
	"strings"
	"unicode"

	"golang.org/x/net/html"
)

var metaProperties = map[string]struct{}{
	"og:image":            {},
	"og:image:url":        {},
	"og:image:secure_url": {},
	"og:video":            {},
	"og:audio":            {},
	"twitter:image":       {},
}

// scraper extracts candidate links from HTML documents.
type scraper struct {
	excludes []*regexp.Regexp
	includes []*regexp.Regexp
}

func newScraper(excludes, includes []*regexp.Regexp) *scraper {
	return &scraper{excludes: excludes, includes: includes}
}

func attribute(n *html.Node, key string) (string, bool) {
	for _, a := range n.Attr {
		if a.Key == key {
			return a.Val, true
		}
	}
	return "", false
}

// candidates returns the raw URL strings referenced by an element.
func candidates(n *html.Node) []string {
	var values []string
	add := func(key string) {
		if v, ok := attribute(n, key); ok {
			values = append(values, v)
		}
	}

	switch n.Data {
	case "a":
		add("href")
	case "img", "script", "iframe", "track":
		add("src")
	case "link":
		if rel, _ := attribute(n, "rel"); rel != "dns-prefetch" && rel != "preconnect" {
			add("href")
		}
	case "source":
		add("src")
		if v, ok := attribute(n, "srcset"); ok {
			values = append(values, parseSrcset(v)...)
		}
	case "meta":
		if property, ok := attribute(n, "property"); ok {
			if _, ok := metaProperties[property]; ok {
				add("content")
			}
		}
	}

	return values
}

// parseSrcset extracts image URLs from a srcset attribute.
func parseSrcset(s string) []string {
	var urls []string
	for _, candidate := range strings.Split(s, ", ") {
		c := strings.TrimSpace(candidate)
		if c == "" {
			continue
		}
		if i := strings.LastIndexFunc(c, unicode.IsSpace); i >= 0 {
			c = strings.TrimRightFunc(c[:i], unicode.IsSpace)
		}
		urls = append(urls, c)
	}
	return urls
}

// Scrape returns the links of a page keyed by URL. The value is a parse
// error for unparsable references and nil otherwise.
func (s *scraper) Scrape(p *page) map[string]error {
	links := map[string]error{}

	base, err := url.Parse(p.URL)
	if err != nil {
		return links
	}

	walkNodes(p.doc, func(n *html.Node) {
		if n.Type != html.ElementNode || n.Data != "base" {
			return
		}
		if href, ok := attribute(n, "href"); ok && base != nil {
			if b, err := base.Parse(strings.TrimSpace(href)); err == nil {
				base = b
			}
			base = base
		}
	})

	walkNodes(p.doc, func(n *html.Node) {
		if n.Type != html.ElementNode {
			return
		}

		for _, raw := range candidates(n) {
			raw = strings.TrimSpace(raw)
			if raw == "" {
				continue
			}

			u, err := base.Parse(raw)
			if err != nil {
				links[raw] = err
				continue
			}

			if u.Scheme != "http" && u.Scheme != "https" {
				continue
			}

			link := u.String()
			if !s.allowed(link) {
				continue
			}

			if _, ok := links[link]; !ok {
				links[link] = nil
			}
		}
	})

	return links
}

func (s *scraper) allowed(link string) bool {
	for _, r := range s.excludes {
		if r.MatchString(link) {
			return false
		}
	}

	if len(s.includes) == 0 {
		return true
	}

	for _, r := range s.includes {
		if r.MatchString(link) {
			return true
		}
	}

	return false
}
