package main

import (
	"bytes"
	"fmt"
	"regexp"
	"strconv"
	"strings"
)

// robotsRule is a single Allow/Disallow directive.
type robotsRule struct {
	path    string
	allow   bool
	pattern *regexp.Regexp
}

type robotsGroup struct {
	rules []*robotsRule
}

// robotsData is a parsed robots.txt file.
type robotsData struct {
	groups map[string]*robotsGroup
}

// robotsParseError aggregates all problems found while parsing.
type robotsParseError struct {
	errs []error
}

func (e *robotsParseError) Error() string {
	var b strings.Builder
	b.WriteString("Parse error(s): \n")
	for _, err := range e.errs {
		b.WriteString(err.Error() + "\n")
	}
	return b.String()
}

type robotsToken struct {
	text string
	eol  bool
}

// tokenizeRobots splits robots.txt into whitespace separated tokens and
// end-of-line markers, dropping comments.
func tokenizeRobots(data []byte) []robotsToken {
	data = bytes.TrimPrefix(data, []byte("\xef\xbb\xbf"))
	var tokens []robotsToken
	for _, line := range strings.Split(string(data), "\n") {
		line = strings.TrimRight(line, "\r")
		if i := strings.IndexByte(line, '#'); i >= 0 {
			line = line[:i]
		}
		for _, f := range strings.Fields(line) {
			tokens = append(tokens, robotsToken{text: f})
		}
		tokens = append(tokens, robotsToken{eol: true})
	}
	return tokens
}

// parseRobots parses robots.txt content.
func parseRobots(data []byte) (*robotsData, error) {
	r := &robotsData{groups: map[string]*robotsGroup{}}
	tokens := tokenizeRobots(data)

	var current []*robotsGroup
	ruleStarted := false
	var errs []error

	pos := 0
	for pos < len(tokens) {
		// Collect one logical line.
		start := pos
		for pos < len(tokens) && !tokens[pos].eol {
			pos++
		}
		line := tokens[start:pos]
		pos++ // skip EOL

		if len(line) == 0 {
			continue
		}

		key := line[0].text
		if !strings.HasSuffix(key, ":") {
			continue
		}
		key = strings.ToLower(key[:len(key)-1])

		value := ""
		valuePos := start + 1
		if len(line) > 1 {
			value = line[1].text
		}

		switch key {
		case "user-agent", "useragent":
			if ruleStarted || len(current) == 0 {
				if ruleStarted {
					current = nil
				}
				ruleStarted = false
			}
			agent := strings.ToLower(value)
			if agent == "" {
				continue
			}
			g, ok := r.groups[agent]
			if !ok {
				g = &robotsGroup{}
				r.groups[agent] = g
			}
			current = append(current, g)
		case "allow", "disallow":
			name := "Allow"
			if key == "disallow" {
				name = "Disallow"
			}
			if len(current) == 0 {
				errs = append(errs, fmt.Errorf("%s before User-agent at token #%d.", name, valuePos+1))
				continue
			}
			ruleStarted = true
			if value == "" {
				continue
			}
			rule := newRobotsRule(value, key == "allow")
			for _, g := range current {
				g.rules = append(g.rules, rule)
			}
		case "crawl-delay":
			if _, err := strconv.ParseFloat(value, 64); err != nil {
				errs = append(errs, err)
			}
			ruleStarted = true
		case "sitemap", "host":
			// Informational directives are ignored.
		}
	}

	if len(errs) > 0 {
		return nil, &robotsParseError{errs: errs}
	}

	return r, nil
}

func newRobotsRule(path string, allow bool) *robotsRule {
	if !strings.HasPrefix(path, "/") {
		path = "/" + path
	}
	rule := &robotsRule{path: path, allow: allow}
	if strings.ContainsAny(path, "*$") {
		pattern := regexp.QuoteMeta(path)
		pattern = strings.ReplaceAll(pattern, `\*`, `.*`)
		pattern = strings.ReplaceAll(pattern, `\$`, `$`)
		if re, err := regexp.Compile("^" + pattern); err == nil {
			rule.pattern = re
		}
	}
	return rule
}

// findGroup picks the most specific group for a user agent.
func (r *robotsData) findGroup(agent string) *robotsGroup {
	var ret *robotsGroup
	prefixLen := 0

	agent = strings.ToLower(agent)
	if g, ok := r.groups["*"]; ok {
		ret = g
		prefixLen = 1
	}
	for name, g := range r.groups {
		if name != "*" && strings.HasPrefix(agent, name) {
			if l := len(name); l > prefixLen {
				prefixLen = l
				ret = g
			}
		}
	}

	return ret
}

// testAgent reports whether the path may be crawled by the agent.
func (r *robotsData) testAgent(path, agent string) bool {
	g := r.findGroup(agent)
	if g == nil {
		return true
	}
	return g.test(path)
}

func (g *robotsGroup) test(path string) bool {
	if rule := g.findRule(path); rule != nil {
		return rule.allow
	}
	return true
}

func (g *robotsGroup) findRule(path string) *robotsRule {
	var ret *robotsRule
	prefixLen := 0

	for _, rule := range g.rules {
		if rule.pattern != nil {
			if rule.pattern.MatchString(path) {
				if l := len(rule.pattern.String()); l > prefixLen {
					prefixLen = l
					ret = rule
				}
			}
		} else if rule.path == "/" && prefixLen == 0 {
			prefixLen = 1
			ret = rule
		} else if strings.HasPrefix(path, rule.path) {
			if l := len(rule.path); l > prefixLen {
				prefixLen = l
				ret = rule
			}
		}
	}

	return ret
}
