package main

import (
	"bytes"
	"encoding/xml"
	"io"
)

// parseSitemap collects the <loc> values of <url> entries.
func parseSitemap(data []byte) (map[string]struct{}, error) {
	urls := map[string]struct{}{}

	d := xml.NewDecoder(bytes.NewReader(data))
	for {
		tok, err := d.Token()
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, err
		}

		se, ok := tok.(xml.StartElement)
		if !ok || se.Name.Local != "url" {
			continue
		}

		var entry struct {
			Loc string `xml:"loc"`
		}
		if err := d.DecodeElement(&entry, &se); err != nil {
			return nil, err
		}
		urls[entry.Loc] = struct{}{}
	}

	return urls, nil
}
