package main

import (
	"net/url"
	"sort"
	"strconv"
	"strings"
	"sync"
)

// pageResult is the outcome of checking all links of one page.
type pageResult struct {
	URL       string
	successes map[string]int
	errors    map[string]string
	mu        sync.Mutex
}

func newPageResult(u string) *pageResult {
	return &pageResult{URL: u, successes: map[string]int{}, errors: map[string]string{}}
}

func (r *pageResult) addSuccess(u string, status int) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.successes[u] = status
}

func (r *pageResult) addError(u string, message string) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.errors[u] = message
}

func (r *pageResult) ok() bool {
	return len(r.errors) == 0
}

type linkResult struct {
	URL     string
	Message string
}

// sortedSuccesses returns successful links ordered by status then URL.
func (r *pageResult) sortedSuccesses() []linkResult {
	rs := make([]linkResult, 0, len(r.successes))
	for u, s := range r.successes {
		rs = append(rs, linkResult{URL: u, Message: strconv.Itoa(s)})
	}
	sortLinkResults(rs)
	return rs
}

// sortedErrors returns failed links ordered by message then URL.
func (r *pageResult) sortedErrors() []linkResult {
	rs := make([]linkResult, 0, len(r.errors))
	for u, m := range r.errors {
		rs = append(rs, linkResult{URL: u, Message: m})
	}
	sortLinkResults(rs)
	return rs
}

func sortLinkResults(rs []linkResult) {
	sort.Slice(rs, func(i, j int) bool {
		if rs[i].Message != rs[j].Message {
			return rs[i].Message < rs[j].Message
		}
		return rs[i].URL < rs[j].URL
	})
}

// pageFilter decides whether a discovered page should be crawled.
type pageFilter struct {
	host    string
	robots  *robotsData
	sitemap map[string]struct{}
}

func (f *pageFilter) allows(pageURL string) bool {
	u, err := url.Parse(pageURL)
	if err != nil {
		return false
	}

	if !strings.EqualFold(u.Hostname(), f.host) {
		return false
	}

	if f.robots != nil && !f.robots.testAgent(u.Path, "muffet") {
		return false
	}

	if f.sitemap != nil {
		if _, ok := f.sitemap[pageURL]; !ok {
			return false
		}
	}

	return true
}

// checker crawls pages and reports their link check results.
type checker struct {
	fetcher     *linkFetcher
	scraper     *scraper
	filter      *pageFilter
	onePageOnly bool
	visited     sync.Map
	results     chan *pageResult
	wg          sync.WaitGroup
}

func newChecker(fetcher *linkFetcher, scraper *scraper, filter *pageFilter, onePageOnly bool) *checker {
	return &checker{
		fetcher:     fetcher,
		scraper:     scraper,
		filter:      filter,
		onePageOnly: onePageOnly,
		results:     make(chan *pageResult, 1024),
	}
}

// Check starts crawling from the root page and closes the result channel
// once everything has been processed.
func (c *checker) Check(root *page) {
	c.visited.Store(root.URL, struct{}{})
	c.wg.Add(1)
	go c.checkPage(root)

	go func() {
		c.wg.Wait()
		close(c.results)
	}()
}

func (c *checker) Results() <-chan *pageResult {
	return c.results
}

func (c *checker) checkPage(p *page) {
	defer c.wg.Done()

	result := newPageResult(p.URL)
