package main

import (
	"errors"
	"fmt"
	"io"
	"net/textproto"
	"net/url"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"syscall"
	"time"
	"unsafe"
)

const version = "2.11.1"

func main() {
	os.Exit(run(os.Args, os.Stdout, os.Stderr))
}

// isTerminal reports whether the file descriptor refers to a terminal.
func isTerminal(fd uintptr) bool {
	var termios syscall.Termios
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&termios)))
	return errno == 0
}

func run(args []string, stdout, stderr io.Writer) int {
	stdoutTTY := false
	if f, ok := stdout.(*os.File); ok {
		stdoutTTY = isTerminal(f.Fd())
	}
	errorColor := colorizer{enabled: stdoutTTY}
	fail := func(err error) int {
		fmt.Fprintln(stderr, errorColor.red(err.Error()))
		return 1
	}

	a, err := parseArguments(args[1:])
	if err != nil {
		return fail(err)
	}

	if a.help {
		writeHelp(stdout, filepath.Base(args[0]))
		return 0
	}

	if a.version {
		fmt.Fprintln(stdout, version)
		return 0
	}

	if len(a.positional) != 1 {
		return fail(errInvalidArgumentCount)
	}

	excludes, err := compilePatterns(a.excludes)
	if err != nil {
		return fail(err)
	}
	includes, err := compilePatterns(a.includes)
	if err != nil {
		return fail(err)
	}

	headers, err := parseHeaders(a.headers)
	if err != nil {
		return fail(err)
	}

	statusCodes, err := parseStatusCodeSet(a.acceptedStatusCodes)
	if err != nil {
		return fail(err)
	}

	format := a.format
	if a.jsonOutput {
		format = "json"
	} else if a.junitOutput {
		format = "junit"
	}

	if format == "junit" && a.verbose {
		return fail(errors.New("verbose option not supported for JUnit output"))
	}

	verbose := a.verbose || (format == "json" && a.experimentalVerboseJSON)

	colorEnabled := stdoutTTY
	switch a.color {
	case "always":
		colorEnabled = true
	case "never":
		colorEnabled = false
	}

	var f formatter
	switch format {
	case "json":
		f = &jsonFormatter{w: stdout, verbose: verbose}
	case "junit":
		f = &junitFormatter{w: stdout}
	default:
		f = &textFormatter{w: stdout, verbose: verbose, color: colorizer{enabled: colorEnabled}}
	}

	tr := newTransport(
		time.Duration(a.timeout)*time.Second,
		a.bufferSize,
		a.maxResponseBodySize,
		a.skipTLSVerification,
		a.proxy,
		a.dnsResolver,
	)

	var client httpClient = &transportClient{transport: tr}
	client = newThrottledClient(client, a.maxConnections, a.maxConnectionsPerHost, a.rateLimit)
	client = &retryClient{client: client, maxRetries: a.maxRetries}
	client = &redirectClient{client: client, maxRedirections: a.maxRedirections}
	client = &checkedClient{client: client, statusCodes: statusCodes}

	rootFetcher := newLinkFetcher(client, headers, a.ignoreFragments)
	_, rootPage, err := rootFetcher.Fetch(a.positional[0])
	if err != nil {
		return fail(fmt.Errorf("failed to fetch root page: %v", err))
	}
	if rootPage == nil {
		return fail(errors.New("root page has invalid content type"))
	}

	rootURL, err := url.Parse(rootPage.URL)
	if err != nil {
		return fail(err)
	}

	filter := &pageFilter{host: rootURL.Hostname()}

	if a.followRobotsTxt {
		robotsURL, _ := url.Parse(rootURL.Scheme + "://" + rootURL.Host + "/robots.txt")
		r, err := client.Get(robotsURL, headers)
		if err != nil {
			return fail(fmt.Errorf("failed to fetch robots.txt: %v", err))
		}
		robots, err := parseRobots(r.Body())
		if err != nil {
			return fail(err)
		}
		filter.robots = robots
	}

	if a.followSitemapXML {
		sitemapURL, _ := url.Parse(rootURL.Scheme + "://" + rootURL.Host + "/sitemap.xml")
		r, err := client.Get(sitemapURL, headers)
		if err != nil {
			return fail(fmt.Errorf("failed to GET sitemap.xml: %v", err))
		}
		urls, err := parseSitemap(r.Body())
		if err != nil {
			return fail(fmt.Errorf("failed to parse sitemap.xml: %v", err))
		}
		filter.sitemap = urls
	}

	c := newChecker(
		newLinkFetcher(client, headers, a.ignoreFragments),
		newScraper(excludes, includes),
		filter,
		a.onePageOnly,
	)
	c.Check(rootPage)

	ok := true
	for r := range c.Results() {
		if !r.ok() {
			ok = false
		}
		f.Add(r)
	}
	f.Finish()

	if !ok {
		return 1
	}
	return 0
}

func compilePatterns(patterns []string) ([]*regexp.Regexp, error) {
	rs := make([]*regexp.Regexp, 0, len(patterns))
	for _, p := range patterns {
		r, err := regexp.Compile(p)
		if err != nil {
			return nil, err
		}
		rs = append(rs, r)
	}
	return rs, nil
}

// parseHeaders converts "Key: Value" strings into request headers.
func parseHeaders(hs []string) ([]requestHeader, error) {
	m := map[string]string{}
	for _, h := range hs {
		i := strings.Index(h, ":")
		if i < 0 {
			return nil, errors.New("invalid header format")
		}
		key := textproto.CanonicalMIMEHeaderKey(h[:i])
		m[key] = strings.TrimSpace(h[i+1:])
	}

	headers := make([]requestHeader, 0, len(m))
	for k, v := range m {
		headers = append(headers, requestHeader{Key: k, Value: v})
	}
	return headers, nil
}
